def test_unchanged_network_functional_result(inputs):
    replayed = loads_compilation_manifest_v0(make_doc(inputs))
    original = compile_case(inputs)
    assert run_network_v0(replayed.network, replayed.initial_events) == run_network_v0(
        original.network, original.initial_events
    )

def test_pipeline_does_not_change_functional_execution(inputs):
    compiled = compile_case(inputs)
    assert run_network_v0(compiled.network, compiled.initial_events) == run_network_v0(
        inputs[1], inputs[2]
    )

def compile_case(scenario, **overrides):
    network, events, resources, architecture, placements = scenario
    arguments = {
        "network_ir_json": dumps_network_ir_v0(network),
        "initial_events": events,
        "resource_profile": resources,
        "architecture": architecture,
        "placements": placements,
    }
    arguments.update(overrides)
    return compile_network_ir_v0(**arguments)

def test_two_neurons_independently_match_oracle():
    network = case()
    img = initialize_neuron_image_v0(network)
    x = apply(network, img, 'A', 3)
    y = apply(network, x.state, 'B', 2)
    oracle = run_network_v0(network, (
        NetworkEventV0(3, 'A', 0), NetworkEventV0(2, 'B', 0),
    ))
    assert {n.node_id: (n.raw, n.last_timestamp) for n in y.state.neurons} == {
        n.node_id: (n.raw, n.last_timestamp) for n in oracle.states
    }
    assert sorted(x.receipt.candidate_outputs + y.receipt.candidate_outputs) == sorted(
        (e.timestamp, e.channel) for e in oracle.emissions
    )
